output_text:
[
  {
    "id": "no_carts_in_single_file_side_aisles",
    "text": "Shopping carts are prohibited in single-file aisles flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "sideShelfAisle": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "sideShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_person_only_aisle",
    "text": "A shopper must not push a cart from a wide aisle into a person-only single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "gt": [
            "freeWidthH",
            1
          ]
        },
        "personOnlyAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterPersonOnlyAisle": {
          "pre": {
            "and": [
              "wideAisle",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "personOnlyAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterPersonOnlyAisle"
        ]
      }
    }
  },
  {
    "id": "cart_shelf_service_only_from_wide_aisles",
    "text": "Shelf interactions while holding a cart are allowed only from wide aisles, not from cramped shelf corridors.",
    "abstraction": {
      "state_properties": {
        "wideCartAisle": {
          "gt": [
            "freeWidthH",
            1
          ]
        },
        "crampedShelfPosition": {
          "and": [
            "adjShelf",
            {
              "not": "wideCartAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "crampedShelfPosition"
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_person_aisle_mouth",
    "text": "A cart may be put down only at the wide mouth of a person-only aisle.",
    "abstraction": {
      "state_properties": {
        "personOnlyAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "personOnlyAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_walking_restricted",
    "text": "A shopper without a cart may walk only in the entry/cart area, at a cart-parking mouth, or inside a person-only aisle.",
    "abstraction": {
      "state_properties": {
        "entryCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "personOnlyAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessAllowedZone": {
          "or": [
            "entryCartArea",
            "personOnlyAisle",
            "cartParkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "cartlessAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart to enter a narrow aisle, the shopper is obliged to retrieve a cart before the trajectory ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "retrieve_cart_after_on_foot_shelf_pick",
    "text": "If an item is taken from a shelf while the shopper is on foot, the shopper must later return to a cart.",
    "abstraction": {
      "state_properties": {
        "shelfPosition": "adjShelf"
      },
      "events": {
        "onFootShelfInteraction": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "shelfPosition"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootShelfInteraction",
      "discharge": "hasCart"
    }
  },
  {
    "id": "do_not_park_cart_for_wide_shelf_access",
    "text": "A shopper should not abandon the cart when the relevant shelf can be accessed directly from a wide aisle.",
    "abstraction": {
      "state_properties": {
        "wideShelfAccess": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          "wideShelfAccess"
        ]
      }
    }
  }
]
